-- 题目默认分值同步到 150 分制（题库界面显示的「默认分值」）
UPDATE question SET score = CASE type
  WHEN 0 THEN 5 WHEN 1 THEN 5 WHEN 2 THEN 3 WHEN 3 THEN 5 WHEN 4 THEN 16
END;
